function example() {
  function MyColumns({ children, ...props }) {
    const { bulmaHelperClasses, rest } = useBulmaClasses(props);
    return (
      <div className={classNames('columns', bulmaHelperClasses)} {...rest}>
        {children}
      </div>
    );
  }

  return (
    <MyColumns textAlign="centered" textTransform="uppercase">
      <div className="column">
        <Notification color="primary">Left</Notification>
      </div>
      <div className="column">
        <Notification color="info">Right</Notification>
      </div>
    </MyColumns>
  );
}

function example() {
  const props = {};

  const textColor = 'white';
  const bgColor = 'primary';
  const hasShadow = true;
  const className = 'custom-card';
  const children = <p>Making a custom card</p>;
  const p = '4';

  const { bulmaHelperClasses, rest } = useBulmaClasses({
    color: textColor,
    backgroundColor: bgColor,
    p,
    ...props,
  });
  const cardClasses = classNames('card', className, bulmaHelperClasses, {
    'is-shadowless': !hasShadow,
  });
  return (
    <div className={cardClasses} {...rest}>
      {children}
    </div>
  );
}

